400	    doc.text('Odoo Quote Comparison', margin, y);
401	    
402	    // Date
403	    doc.setFontSize(9);
404	    doc.setFont('helvetica', 'normal');
405	    doc.setTextColor(130, 130, 130);
406	    doc.text(new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }), pageWidth - margin, y, { align: 'right' });
407	    
408	    y += 12;
409	
410	    // Configuration row
411	    doc.setFillColor(248, 248, 248);
412	    doc.roundedRect(margin, y - 4, pageWidth - (margin * 2), 16, 2, 2, 'F');
413	    
414	    doc.setFontSize(8);
415	    doc.setTextColor(100, 100, 100);
416	    const configs = [
417	      `Users: ${users}`,
418	      `Plan: ${plan === 'standard' ? 'Standard' : 'Custom'}`,
419	      `Currency: ${countryConfig.currency}`,
420	      `Impl: ${currentImplementations[implementation as keyof typeof currentImplementations]?.label || 'None'}`
421	    ];
422	    doc.text(configs.join('   •   '), margin + 6, y + 5);
423	    
424	    y += 22;
425	
426	    // Table setup
