434	    const hasAnySavings = quoteData.some(d => d.totalSavings > 0);
435	    const hasAnyFinancing = quoteData.some(d => d.financingLow > 0);
436	
437	    // Draw table header row
438	    doc.setFillColor(113, 75, 103);
439	    doc.rect(margin, y, tableWidth, rowHeight + 2, 'F');
440	    
441	    doc.setFont('helvetica', 'bold');
442	    doc.setFontSize(8);
